int snd_dmaengine_pcm_open_request_chan(struct snd_pcm_substream *substream)
{
	struct dma_chan *chan;
	struct dmaengine_pcm_runtime_data *prtd;

	syslog(LOG_ERR, "[dm] dmaengine open_request_chan stream=%d\n",
	       substream->stream);
	chan = dma_request_channel();
	if (!chan)
		return -ENXIO;
	prtd = snd_malloc(sizeof(struct dmaengine_pcm_runtime_data));
	if (!prtd)
		return -ENOMEM;
	prtd->dma_chan = chan;
	substream->runtime->private_data = prtd;
	syslog(LOG_ERR, "[dm] dmaengine open_request_chan done chan=%p\n", chan);

	return 0;
}

int snd_dmaengine_pcm_close_release_chan(struct snd_pcm_substream *substream)
{
	struct dmaengine_pcm_runtime_data *prtd = substream_to_prtd(substream);

	syslog(LOG_ERR, "[dm] dmaengine close_release_chan stream=%d chan=%p\n",
	       substream->stream, prtd ? prtd->dma_chan : NULL);
	dma_release_channel(prtd->dma_chan);
	snd_free(prtd);
	substream->runtime->private_data = NULL;
	return 0;
}

