static int dmaengine_pcm_prepare_and_submit(struct snd_pcm_substream *substream)
{
	struct dmaengine_pcm_runtime_data *prtd = substream_to_prtd(substream);
	struct dma_chan *chan = prtd->dma_chan;
	enum dma_transfer_direction direction;
	int ret = 0;
	dma_callback callback;

	direction = snd_pcm_substream_to_dma_direction(substream);

	prtd->pos = 0;

	/* flush ringbuffer */
	hal_dcache_clean_invalidate((unsigned long)(substream->runtime->dma_addr),
				snd_pcm_lib_buffer_bytes(substream));

	syslog(LOG_ERR, "[dm] dma prep_cyclic chan=%p buf=%lx bytes=0x%x period=0x%x dir=%d\n",
	       chan, (unsigned long)substream->runtime->dma_addr,
	       (unsigned int)snd_pcm_lib_buffer_bytes(substream),
	       (unsigned int)snd_pcm_lib_period_bytes(substream), direction);
	ret = dmaengine_prep_dma_cyclic(chan,
		substream->runtime->dma_addr,
		snd_pcm_lib_buffer_bytes(substream),
		snd_pcm_lib_period_bytes(substream), direction);
	if (ret != 0) {
		snd_err("[%s] dma cyclic failed!!!\n", __func__);
		return ret;
	}
	callback = dmaengine_pcm_dma_complete;

	syslog(LOG_ERR, "[dm] dma submit chan=%p\n", chan);
	dmaengine_submit(chan, callback, (void *)substream);

	return 0;
}

